import { createState, collides, step, frame } from '../game/neon.js';

// Mock canvas context
const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1 - Ball does not bounce off bricks', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball so it collides with the bottom of the first brick
  // Brick 0: x=offsetX, y=BRICK_TOP, w=BRICK_W, h=BRICK_H
  // ball.y + ball.r > brick.y AND ball.y - ball.r < brick.y + brick.h
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Slightly below the brick
  state.ball.vy = -100; // Moving UP

  // The current 'collides' check in 'frame' only marks the brick as dead
  // it doesn't change ball.vy.
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, -100, 'Ball vy should still be -100 (this test proves the bug by showing it DOES NOT change)');
  // Wait, to prove the bug, the test should express the EXPECTED behavior (bounce) and fail because the actual behavior is no bounce.
});

import { assert } from 'node:assert';
import { createState, frame, BRICK_TOP, BRICK_H, BRICK_W } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1 - Ball should bounce off the bottom of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below the brick
  state.ball.vy = -100; // Moving UP

  frame(mockCtx, state);

  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN (vy > 0)');
});

test('D2 - Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x - 2; // Just to the left
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving RIGHT
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT (vx < 0)');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should remain 0');
});

test('D3 - Ball should not get stuck inside a brick (Repositioning)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball deep inside the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = -100;

  frame(mockCtx, state);

  // Check if ball is now outside the brick (simple AABB check)
  const isStillInside = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );

  assert.strictEqual(isStillInside, false, 'Ball should be repositioned outside the brick');
});

