test('frame: ball should not tunnel through brick at high speed (D4)', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1; 
  state.ball.vy = 1000; // Very fast

  // In a real game, this would be processed in step() then frame().
  // Since we are testing frame(), we simulate the state AFTER a large step.
  // If the ball moves 1000 * 0.05 = 50px, it will be at y = 51.
  // The brick is at y = 48 to 68.
  // So it should still collide if the logic is "swept".
  // But our current logic is "discrete" (only checks current position).

  // Let's simulate the position after a jump that would tunnel.
  state.ball.y = brick.y + brick.h + 1; // Now it's just below the brick
  // If we just call frame(), it only checks if the ball is CURRENTLY overlapping.
  // If it's at y = 69 and r = 7, it still overlaps (69 - 7 = 62 < 68).
  // To truly tunnel, it needs to be further.
  state.ball.y = brick.y + brick.h + 8; // 68 + 8 = 76.
  // Now ball.y - ball.r = 76 - 7 = 69.
  // Brick bottom is 68. 69 > 68. NO OVERLAP.

  frame(mockCtx, state);

  // If it tunneled, it didn't bounce.
  // We expect it to have bounced.
  assert.ok(state.ball.vy < 0, 'Ball should have bounced back UP');
});

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Handles collision between the ball and all alive bricks.
// Returns true if any brick was broken.
export function resolveBrickCollisions(state) {
  let hit = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const closestX = Math.max(brick.x, Math.min(state.ball.x, brick.x + brick.w));
      const closestY = Math.max(brick.y, Math.min(state.ball.y, brick.y + brick.h));

      const diffX = state.ball.x - closestX;
      const diffY = state.ball.y - closestY;
      const distance = Math.sqrt(diffX * diffX + diffY * diffY);

      if (distance > 0) {
        const nx = diffX / distance;
        const ny = diffY / distance;
        const dot = state.ball.vx * nx + state.ball.vy * ny;
        state.ball.vx -= 2 * dot * nx;
        state.ball.vy -= 2 * dot * ny;
        state.ball.x = closestX + nx * state.ball.r;
        state.ball.y = closestY + ny * state.ball.r;
      } else {
        const dx1 = state.ball.x - brick.x;
        const dx2 = brick.x + brick.w - state.ball.x;
        const dy1 = state.ball.y - brick.y;
        const dy2 = brick.y + brick.h - state.ball.y;
        const min = Math.min(dx1, dx2, dy1, dy2);
        if (min === dx1) {
          state.ball.x = brick.x - state.ball.r;
          state.ball.vx = -Math.abs(state.ball.vx);
        } else if (min === dx2) {
          state.ball.x = brick.x + brick.w + state.ball.r;
          state.ball.vx = Math.abs(state.ball.vx);
        } else if (min === dy1) {
          state.ball.y = brick.y - state.ball.r;
          state.ball.vy = Math.abs(state.ball.vy);
        } else {
          state.ball.y = brick.y + brick.h + state.ball.r;
          state.ball.vy = -Math.abs(state.ball.vy);
        }
      }
      hit = true;
      break; // Only one brick collision per frame to avoid double-bounce
    }
  }
  return hit;
}

