// neon.test.js — PARTIAL coverage (on purpose).
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  frame,
  resolveBrickCollisions,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D1 - Ball should bounce off the bottom of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2;
  state.ball.vy = -100;
  resolveBrickCollisions(state);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced DOWN');
});

test('D2 - Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;
  resolveBrickCollisions(state);
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should remain 0');
});

test('D3 - Ball should not get stuck inside a brick (Repositioning)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = -100;
  resolveBrickCollisions(state);
  const isStillInside = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );
  assert.strictEqual(isStillInside, false, 'Ball should be repositioned outside');
});

test('D4 - Ball should not tunnel through brick at high speed', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1; 
  state.ball.vy = 1000; 

  // In our new implementation, we use sub-stepping in step()
  // If we take a large step, it should still collide.
  step(state, 0.05); 

  assert.ok(state.ball.vy < 0, 'Ball should have bounced back UP');
});

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});
